#!/usr/bin/env python3
"""Final polish for Fah Mai A4 example cards and valid lazy-loading markup."""
from pathlib import Path
import re

p=Path('proposals/fah-mai/index.html')
s=p.read_text(encoding='utf-8')
assert 'id="fahmai-responsive-reader-v23"' in s
assert 'id="examples-client"' in s
# Correct markup generated by the v23 image-laziness conversion. The source
# used self-closing IMG tags, so new attributes must precede the /> delimiter.
s,n=re.subn(r'/\s+loading="lazy"\s+decoding="async">',' loading="lazy" decoding="async" />',s)
print('CORRECTED_IMG_TAGS',n)
# Decode thumbnail artwork only when that Examples sheet is visited.
begin=s.find('id="overview"')
end=s.find('</article>',begin)
prefix,suffix=s[:end],s[end:]
suffix,m=re.subn(r'(<img\b[^>]*\bloading=)"eager"',r'\1"lazy"',suffix)
s=prefix+suffix
print('DEFERRED_EXAMPLE_IMAGES',m)
# Both Examples sheets were 31-36px too tall at their A4 intrinsic scale.
# Keep the readable copy and trim ~23px per thumbnail row instead of hiding
# content under the page footer or inserting an awkward nested scrollbar.
css='''\n<style id="fahmai-examples-a4-fit-v24">
@media screen, print {
 #examples .example-media,
 #examples-client .example-media {
   height:145px!important;
   min-height:145px!important;
   max-height:145px!important;
   flex:0 0 145px!important;
 }
 #examples .example-grid,
 #examples-client .example-grid {
   row-gap:12px!important;
 }
}
</style>\n'''
assert 'id="fahmai-examples-a4-fit-v24"' not in s
s=s.replace('</head>',css+'</head>',1)
p.write_text(s,encoding='utf-8')
print('FINAL_EXAMPLES_HTML_BYTES',p.stat().st_size)
